  Q['6.3.2'] = { spec: 'TS 38.331', text: 'The IE AdditionalPCIIndex identifies an additional physical cell identity (PCI) configured with additionalPCI-ToAddModList-r17 in ServingCellConfig. AdditionalPCIIndex information element -- ASN1START -- TAG-ADDITIONALPCIINDEX-START AdditionalPCIIndex-r17 ::= INTEGER(1..maxNrofAdditionalPCI-r17) -- TAG-ADDITIONALPCIINDEX-STOP -- ASN1STOP The IE AdditionalSpectrumEmission is used to indicate emission requirements to be fulfilled by the UE (see TS 38.101-1 [15], clause 6.2.3/6.2A.3, TS 38.101-2 [39], clause…' };
